import type { UserProfile } from "./userProfileTypes"

/**
 * Threshold for showing warning when trial is expiring soon (in days)
 */
export const DAYS_WARNING_THRESHOLD = 5

/**
 * Trial status information
 */
export interface TrialStatus {
	/** Whether the profile has a trial plan */
	isTrial: boolean
	/** Days remaining until trial expires (null if not a trial or no refresh_at) */
	daysRemaining: number | null
	/** Whether the trial has expired */
	isExpired: boolean
	/** Whether the trial is expiring soon (within warning threshold) */
	isExpiringSoon: boolean
}

/**
 * Check if a profile has a trial plan
 *
 * @param profile - The user profile to check
 * @returns True if the profile has a trial plan
 */
export function isTrial(profile: UserProfile | null | undefined): boolean {
	return profile?.plan?.includes("ibm_bob_trial") ?? false
}

/**
 * Calculate trial status information for a user profile
 *
 * @param profile - The user profile to check
 * @returns Trial status information
 */
export function getTrialStatus(profile: UserProfile | null | undefined): TrialStatus {
	const isTrialPlan = isTrial(profile)

	if (!isTrialPlan || !profile?.refresh_at) {
		return {
			isTrial: isTrialPlan,
			daysRemaining: null,
			isExpired: false,
			isExpiringSoon: false,
		}
	}

	const now = Date.now()
	const refreshTime = profile.refresh_at * 1000
	const diffMs = refreshTime - now
	const daysRemaining = Math.ceil(diffMs / (1000 * 60 * 60 * 24))

	const isExpired = daysRemaining <= 0
	const isExpiringSoon = daysRemaining > 0 && daysRemaining < DAYS_WARNING_THRESHOLD

	return {
		isTrial: isTrialPlan,
		daysRemaining,
		isExpired,
		isExpiringSoon,
	}
}

/**
 * Format a refresh_at timestamp as a localized date string
 *
 * @param refreshAt - Unix timestamp (seconds) of the refresh date
 * @param locale - Locale string for formatting (e.g., 'en', 'de')
 * @param includeYear - Whether to include the year in the formatted date (default: false)
 * @returns Formatted date string
 */
export function formatRefreshDate(refreshAt: number, locale: string = "en", includeYear: boolean = false): string {
	const refreshDate = new Date(refreshAt * 1000)
	return refreshDate.toLocaleDateString(locale, {
		month: "short",
		day: "numeric",
		...(includeYear && { year: "numeric" }),
	})
}

/**
 * Check if a refresh date is in the past
 *
 * @param refreshAt - Unix timestamp (seconds) of the refresh date
 * @returns True if the date is in the past
 */
export function isRefreshDateInPast(refreshAt: number): boolean {
	const refreshDate = new Date(refreshAt * 1000)
	const now = new Date()
	return refreshDate < now
}

/**
 * Get the display name for a user's plan
 *
 * Returns the plan_name if available (Gateway API only), otherwise falls back to the plan field
 * with the 'ibm_bob_' prefix removed for better readability.
 * This ensures consistent display of plan information across UI components while maintaining
 * backward compatibility with legacy LiteLLM responses that don't include plan_name.
 *
 * @param profile - The user profile to get the plan display name from
 * @returns The plan display name, or undefined if neither field is set
 */
export function getPlanDisplayName(profile: UserProfile | null | undefined): string | undefined {
	if (profile?.plan_name) {
		return profile.plan_name
	}

	if (profile?.plan) {
		return profile.plan.replace(/^ibm_bob_/, "")
	}

	return undefined
}

/**
 * Determine whether team information should be displayed based on instance/team structure.
 *
 * Display logic:
 * - Case 1: Multiple instances with multiple teams → show team info
 * - Case 2: Single instance, multiple teams → show team info
 * - Case 3: Multiple instances, single team per instance → hide team info
 *
 * @param profiles - Array of available user profiles
 * @returns True if team info should be shown, false otherwise
 */
export function shouldShowTeamInfo(profiles: UserProfile[] | null | undefined): boolean {
	if (!profiles || profiles.length < 2) {
		return false
	}

	// Count teams per instance
	const teamsPerInstance = new Map<string, number>()
	for (const profile of profiles) {
		const instanceId = profile.instance_id || "default"
		teamsPerInstance.set(instanceId, (teamsPerInstance.get(instanceId) || 0) + 1)
	}

	// Case 3: If all instances have exactly 1 team, don't show team info
	const allSingleTeam = Array.from(teamsPerInstance.values()).every((count) => count === 1)
	if (allSingleTeam && teamsPerInstance.size > 1) {
		return false
	}

	// Case 1 & 2: Show team info
	return true
}

