import { useExtensionState } from "@/context/ExtensionStateContext" // ibm_change

// Fallback URL if DOCS_LINK is not set in environment // ibm_change
const DEFAULT_DOCS_URL = "http://bob.ibm.com/docs/ide" // ibm_change

/**
 * Pure utility for building Bob documentation links with UTM telemetry. // ibm_change
 *
 * @param baseUrl - The docs root URL
 * @param path - The path after the docs root (no leading slash)
 * @param campaign - The UTM campaign context (e.g. "welcome", "provider_docs", "tips", "error_tooltip")
 * @returns The full docs URL with UTM parameters
 */
export function buildDocLink(baseUrl: string, path?: string, campaign?: string): string {
	// ibm_change
	if (path && campaign) {
		// Replace "roo" with "bob" in path and campaign
		path = path.replace(/roo/g, "bob")
		campaign = campaign.replace(/roo/g, "bob")

		// Remove any leading slash from path
		const cleanPath = path.replace(/^\//, "")
		const [basePath, hash] = cleanPath.split("#")

		const url = `${baseUrl}/${basePath}/#${encodeURIComponent(campaign)}` // ibm_change
		return hash ? `${url}#${hash}` : url
	}
	return baseUrl
}

/**
 * Hook that returns a buildDocLink function bound to the current docs-link feature flag. // ibm_change
 */
// ibm_change_start
export function useBuildDocLink() {
	const { featureFlags } = useExtensionState()
	const baseUrl = featureFlags?.["docs-link"] ?? DEFAULT_DOCS_URL

	return (path?: string, campaign?: string) => buildDocLink(baseUrl, path, campaign)
}
// ibm_change_end
