import { vscode } from "@/utils/vscode"
import { ExtensionMessage } from "@roo/ExtensionMessage"

/**
 * Simple function to launch SSO and wait for a response.
 * Timeout is handled on the backend.
 */

interface SsoResponse {text?: string};

export function launchSso() {
	return new Promise<SsoResponse>((resolve, _) => {
		const cleanup = () => {
			window.removeEventListener("message", handler)
		}

		const handler = (event: MessageEvent) => {
			const message: ExtensionMessage = event.data

			if (message.type === "ssoReady") {
				cleanup()
				resolve({message} as SsoResponse);
			}
		}

		window.addEventListener("message", handler)
		vscode.postMessage({
			type: "ibmSSOFlow",
		})
	})
}
