import { vscode } from "../../utils/vscode"

export type LogLevel = "debug" | "info" | "warn" | "error" | "fatal"

export interface LogMeta {
	ctx?: string
	[key: string]: any
}

/**
 * Logger class for webview that sends messages to backend's CompactLogger
 */
class WebviewLogger {
	private defaultContext?: string

	constructor(defaultContext?: string) {
		this.defaultContext = defaultContext
	}

	/**
	 * Logs a debug level message
	 * @param message - The message to log
	 * @param meta - Optional metadata to include
	 */
	debug(message: string, meta?: LogMeta): void {
		this.log("debug", message, meta)
	}

	/**
	 * Logs an info level message
	 * @param message - The message to log
	 * @param meta - Optional metadata to include
	 */
	info(message: string, meta?: LogMeta): void {
		this.log("info", message, meta)
	}

	/**
	 * Logs a warning level message
	 * @param message - The message to log
	 * @param meta - Optional metadata to include
	 */
	warn(message: string, meta?: LogMeta): void {
		this.log("warn", message, meta)
	}

	/**
	 * Logs an error level message
	 * @param message - The error message or Error object
	 * @param errorOrMeta - Optional error object or metadata to include
	 */
	error(message: string | Error, errorOrMeta?: Error | LogMeta): void {
		this.handleErrorLog("error", message, errorOrMeta)
	}

	/**
	 * Logs a fatal level message
	 * @param message - The error message or Error object
	 * @param errorOrMeta - Optional error object or metadata to include
	 */
	fatal(message: string | Error, errorOrMeta?: Error | LogMeta): void {
		this.handleErrorLog("fatal", message, errorOrMeta)
	}

	/**
	 * Creates a child logger with additional context
	 * @param meta - Additional metadata for the child logger
	 * @returns A new logger instance with combined metadata
	 */
	child(meta: LogMeta): WebviewLogger {
		const childLogger = new WebviewLogger(this.defaultContext)
		// Store the parent's default context and merge with child meta
		const combinedContext = meta.ctx || this.defaultContext
		childLogger.defaultContext = combinedContext
		return childLogger
	}

	/**
	 * Handles logging of error and fatal messages with special error object processing
	 * @private
	 */
	private handleErrorLog(level: "error" | "fatal", message: string | Error, errorOrMeta?: Error | LogMeta): void {
		let logMessage: string
		let logMeta: LogMeta | undefined

		// Handle when message is an Error object
		if (message instanceof Error) {
			logMessage = message.message
			const meta = errorOrMeta instanceof Error ? undefined : errorOrMeta
			logMeta = {
				...meta,
				ctx: meta?.ctx ?? this.defaultContext ?? level,
				error: {
					name: message.name,
					message: message.message,
					stack: message.stack,
				},
			}
		} else {
			// Handle when message is a string
			logMessage = message

			// If errorOrMeta is an Error object, extract its information
			if (errorOrMeta instanceof Error) {
				logMeta = {
					ctx: this.defaultContext ?? level,
					error: {
						name: errorOrMeta.name,
						message: errorOrMeta.message,
						stack: errorOrMeta.stack,
					},
				}
			} else {
				logMeta = errorOrMeta
			}
		}

		this.log(level, logMessage, logMeta)
	}

	/**
	 * Core logging function that sends messages to the backend
	 * @private
	 */
	private log(level: LogLevel, message: string, meta?: LogMeta): void {
		const finalMeta = meta ? { ...meta } : {}
		
		// Add default context if not already present
		if (!finalMeta.ctx && this.defaultContext) {
			finalMeta.ctx = this.defaultContext
		}

		vscode.postMessage({
			type: "logToBackend",
			text: message,
			logLevel: level,
			logMeta: Object.keys(finalMeta).length > 0 ? finalMeta : undefined,
		})
	}
}

/**
 * Default logger instance for the webview
 * Usage:
 * ```typescript
 * import { logger } from './utils/logger'
 * 
 * logger.info('User clicked button', { ctx: 'ui', buttonId: 'submit' })
 * logger.error('API call failed', new Error('Network timeout'))
 * 
 * // Create a child logger with context
 * const apiLogger = logger.child({ ctx: 'api' })
 * apiLogger.debug('Fetching data from endpoint')
 * ```
 */
export const logger = new WebviewLogger()

/**
 * Create a logger with a specific context
 * @param context - The context string for this logger
 * @returns A new logger instance with the specified context
 */
export function createLogger(context: string): WebviewLogger {
	return new WebviewLogger(context)
}

