import * as React from "react"

interface ToggleButtonProps {
	checked: boolean
	onChange: (checked: boolean) => void
	disabled?: boolean
	noContainer?: boolean
	icon?: React.ReactNode
	size?: "default" | "compact"
}

const ToggleButton: React.FC<ToggleButtonProps> = ({ checked, onChange, disabled = false, noContainer, icon, size = "default" }) => {
	// Size-specific dimensions
	const isCompact = size === "compact"
	const trackWidth = isCompact ? "w-8" : "w-10"
	const trackHeight = isCompact ? "h-4" : "h-5"
	const thumbSize = isCompact ? "h-3 w-3" : "h-4 w-4"
	const thumbPosition = isCompact ? "left-0.5 bottom-0.5" : "left-0.5 bottom-0.5"
	const thumbTranslate = isCompact ? "translate-x-4" : "translate-x-5"
	const iconSize = isCompact ? "[&>svg]:h-3 [&>svg]:w-3" : "[&>svg]:h-4 [&>svg]:w-4"
	const iconPosition = isCompact ? "[&>svg]:left-0.5 [&>svg]:bottom-0.5" : "[&>svg]:left-1 [&>svg]:bottom-0.5"
	
	const toggle = (
		<label
			className={`flex items-center relative ${
				disabled ? "cursor-not-allowed" : "cursor-pointer"
			} ${noContainer ? `${trackWidth} ${trackHeight}` : "pl-[50px] h-6"}`}>
			<input
				type="checkbox"
				className="opacity-0 w-0 h-0"
				checked={checked}
				onChange={(e) => onChange(e.target.checked)}
				disabled={disabled}
			/>
			<span
				className={`absolute top-0 left-0 right-0 bottom-0 ${trackWidth} ${trackHeight} rounded-[20px] transition-all duration-[400ms] cursor-pointer ${
					disabled
						? "bg-vscode-disabledForeground"
						: checked
							? "bg-vscode-button-background"
							: "bg-vscode-disabledForeground"
				}`}>
				<span
					className={`absolute ${thumbSize} ${thumbPosition} rounded-full bg-vscode-button-foreground transition-transform duration-[400ms] ${
						checked ? thumbTranslate : ""
					}`}
				/>
			</span>
			{checked && icon ? (
				<span className={`[&>svg]:absolute ${iconSize} ${iconPosition}`}>
					{icon}
				</span>
			) : null}
		</label>
	)
	if (noContainer) {
		return toggle
	}
	return <div className="my-2.5">{toggle}</div>
}

export default ToggleButton

