import { useMemo } from "react"
import { useExtensionState } from "../../context/ExtensionStateContext"
import { FeatureFlags } from "@roo/IBM/featureFlagsType"
import { isTestEnvironment, defaultMockFeatureFlags } from "../../utils/test-feature-flags"

/**
 * A React hook that provides selective access to individual feature flags in the application.
 *
 * This hook retrieves a specific feature flag from the ExtensionStateContext and uses
 * memoization to prevent unnecessary re-renders. By requesting only the specific flag
 * needed, components will only re-render when that particular flag changes, improving
 * performance compared to destructuring from a full feature flags object.
 *
 * Feature flags are managed by the FeatureFlagManager in the backend and are
 * synchronized with the webview via the ExtensionStateContext. The flags can
 * be dynamically updated from the server or through local configuration.
 *
 * @template T - The key of the feature flag to retrieve
 * @param {T} flagName - The name of the feature flag to retrieve
 * @returns {FeatureFlags[T] | undefined} The value of the requested feature flag, or undefined if not available
 *
 * @example
 * // Access a specific feature flag
 * const bobTermsRequired = useFeatureFlag('bobTermsRequired');
 * if (bobTermsRequired) {
 *   // Show terms and conditions
 * }
 *
 * @example
 * // Access multiple feature flags (call the hook multiple times)
 * const liteLLMBaseUrl = useFeatureFlag('liteLLMBaseUrl');
 * const bobReskinEnabled = useFeatureFlag('bobReskinEnabled');
 * const marketplaceEnabled = useFeatureFlag('marketplaceEnabled');
 */
export function useFeatureFlag<T extends keyof FeatureFlags>(flagName: T): FeatureFlags[T] {
	const context = useExtensionState()
	const currentValue = useMemo(() => {
		const featureFlags = context.featureFlags
		if (!featureFlags) {
			// In production and development, feature flags should be initialized before UI renders
			// Only in test environment, we'll use default mock feature flags
			if (isTestEnvironment()) {
				// Use type assertion with unknown as intermediate step to avoid TypeScript errors
				return (defaultMockFeatureFlags as unknown as FeatureFlags)[flagName];
			}
			// Throw in development and production environments to catch issues early
			throw Error("Feature flags used before intialising with value");
		}
		return featureFlags[flagName]
	}, [context.featureFlags, flagName])
	return currentValue
}
