export const defaultTestEnvConfig: EnvConfig = {
	gatewayBaseUrl: "", // ibm_change
	telemetryMaxBatchSizeBytes: 1048576, // 1MB
	telemetryFlushIntervalMs: 120000, // 120 seconds
}

/**
 * Helper function to check if code is running in a test environment
 */
export function isTestEnvironment(): boolean {
  return (
    process.env.NODE_ENV === 'test' ||
    process.env.VITEST !== undefined ||
    (typeof process !== 'undefined' && process.env?.JEST_WORKER_ID !== undefined)
  );
}

