import { Button } from "@/components/ui"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { Wrench } from "lucide-react"
import { useState } from "react"
import { VSCodeTextField, VSCodeLink } from "@vscode/webview-ui-toolkit/react"
import { inputEventTransform } from "@/components/settings/transforms"
import { vscode } from "@/utils/vscode"
import { useFeatureFlag } from "@/ibm/hooks/useFeatureFlag"
import { launchSso } from "@/ibm/utils/sso"
import { useExtensionState } from "@/context/ExtensionStateContext"

const AutoSetup: React.FC<unknown> = () => {
	const { t } = useAppTranslation()
	const { envConfig } = useExtensionState()
	const [isSpinning, setIsSpinning] = useState(false)
	const apikeySigninAllowed = useFeatureFlag("apikey-signin-allowed")
	const ssoSigninAllowed = useFeatureFlag("sso-signin-allowed")
	const trialSignupUrl = useFeatureFlag("trial-signup-url")
	const liteLLMBaseUrl = envConfig?.gatewayBaseUrl
	const [apiKey, setApiKey] = useState("")
	const [ssoWaiting, setSsoWaiting] = useState(false)
	const [errorMessage, setErrorMessage] = useState("")

	// We need to enable it if they are both disabled by accident.
	const useApiKeySignin = apikeySigninAllowed || (apikeySigninAllowed === false && ssoSigninAllowed === false)

	const handleSubmit = () => {
		const premiumConfig = {
			apiProvider: "litellm" as const,
			apiModelId: "premium",
			litellmModelId: "premium",
			litellmBaseUrl: liteLLMBaseUrl,
			litellmApiKey: apiKey,
		}
		vscode.postMessage({
			type: "renameApiConfiguration",
			values: { oldName: "default", newName: "Premium" },
			apiConfiguration: premiumConfig,
		})
	}

	const errorResult = (tString: string) => {
		setErrorMessage(tString)
		setIsSpinning(false)
	}

	const handleButtonClick = async () => {
		setIsSpinning(true)

		try {
			// Use setTimeout to ensure the config is set before submitting
			// and spin for the button shows
			setTimeout(() => handleSubmit(), 300)
		} catch (_e) {
			errorResult(t("welcome:startAutoSetupApiKeyError"))
		}
	}

	const handleSSOSignIn = () => {
		// Initiate SSO sign-in flow
		// setIsSpinning(true);
		// Open the SSO authentication URL in the browser

		setSsoWaiting(true)
		launchSso().then((response) => {
			setSsoWaiting(false)
			if (response.text) {
				errorResult(response.text)
			}
		})
	}

	return (
		<div className="flex flex-col gap-4 justify-center items-center p-6 w-full">
			{useApiKeySignin ? (
				<div className="flex flex-col gap-4 justify-center items-center p-6 w-full">
					<div className="w-full px-2">
						<VSCodeTextField
							value={apiKey}
							onInput={(e) => setApiKey(inputEventTransform(e))}
							placeholder={t("welcome:startAutoSetupApiKeyPlaceholder")}
							className="w-full">
							<label className="block font-medium mb-1">{t("welcome:startAutoSetupApiKey")}</label>
						</VSCodeTextField>
					</div>
					{errorMessage && <div className="text-vscode-errorForeground w-full px-2 mt-1">{errorMessage}</div>}

					<Button
						onClick={handleButtonClick}
						className="font-medium py-6 px-12 rounded-xl bg-vscode-button-background transition-all duration-300 flex items-center gap-2"
						disabled={ssoWaiting || !apiKey}>
						{t("welcome:startAutoSetupButton")}
						<Wrench className={`w-5 h-5 ${isSpinning ? "animate-spin" : ""}`} />
					</Button>
				</div>
			) : null}

			{apikeySigninAllowed && ssoSigninAllowed ? (
				<div className="mt-4 text-center">
					<span className="text-vscode-descriptionForeground">{t("welcome:or")}</span>
				</div>
			) : null}

			{ssoSigninAllowed ? (
				<>
					<Button
						size="lg"
						onClick={handleSSOSignIn}
						disabled={ssoWaiting}
						className="mt-4 rounded-lg px-10"
						variant="primary">
						{t("welcome:signInSSO")}
					</Button>

					<p className="text-vscode-descriptionForeground mb-0 font-medium max-w-[300px]">
						{t("ibm:welcome.noSubscription")}
					</p>
					<VSCodeLink href={trialSignupUrl}>
						<Button className="rounded-lg px-8" variant="secondary" asChild>
							<span>{t("ibm:welcome.signUp")}</span>
						</Button>
					</VSCodeLink>

					<VSCodeLink href={"https://www.ibm.com/privacy"}>{t("welcome:privacyPolicy")}</VSCodeLink>
				</>
			) : null}
		</div>
	)
}

export default AutoSetup
