/**
 * Message Listener Utility
 * 
 * Provides a reusable utility for setting up one-time message listeners with automatic
 * cleanup and timeout protection. This prevents memory leaks and ensures proper cleanup
 * in all scenarios (success, error, or timeout).
 * 
 * @example
 * ```typescript
 * // Simple usage with timeout
 * const cleanup = createMessageListener({
 *   messageType: 'marketplaceInstallResult',
 *   matchCondition: (message) => message.slug === 'my-mode',
 *   onSuccess: (message) => {
 *     console.log('Installation successful!', message);
 *   },
 *   onError: (error) => {
 *     console.error('Installation failed:', error);
 *   },
 *   timeout: 30000 // 30 seconds
 * });
 * 
 * // Manual cleanup if needed (e.g., component unmount)
 * cleanup();
 * ```
 * 
 * @example
 * ```typescript
 * // Nested listeners for sequential operations
 * createMessageListener({
 *   messageType: 'marketplaceRemoveResult',
 *   matchCondition: (message) => message.slug === mode.slug,
 *   onSuccess: (message) => {
 *     // First operation succeeded, start second operation
 *     vscode.postMessage({ type: 'installMarketplaceItem', ... });
 *     
 *     // Set up listener for second operation
 *     createMessageListener({
 *       messageType: 'marketplaceInstallResult',
 *       matchCondition: (msg) => msg.slug === mode.slug,
 *       onSuccess: () => console.log('Reinstall complete!'),
 *       onError: (err) => console.error('Reinstall failed:', err),
 *       timeout: 30000
 *     });
 *   },
 *   onError: (error) => {
 *     console.error('Remove failed:', error);
 *   },
 *   timeout: 30000
 * });
 * ```
 */

/**
 * Configuration for creating a message listener
 */
export interface MessageListenerConfig<T = any> {
	/**
	 * The message type to listen for (e.g., 'marketplaceInstallResult')
	 */
	messageType: string

	/**
	 * Optional condition to match specific messages of the given type.
	 * Return true if the message should be handled, false otherwise.
	 *
	 * @example
	 * ```typescript
	 * matchCondition: (message) => message.slug === 'my-mode-slug'
	 * ```
	 */
	matchCondition?: (message: T) => boolean

	/**
	 * Callback invoked when a matching message is received successfully.
	 *
	 * Return true to keep the listener active (for persistent listeners),
	 * or false/undefined to clean up the listener after this callback.
	 *
	 * @param message - The received message data
	 * @returns true to keep listening, false/undefined to cleanup
	 */
	onSuccess: (message: T) => boolean | void

	/**
	 * Callback invoked when an error occurs (message.success === false or timeout).
	 * The listener is automatically cleaned up after this callback.
	 *
	 * @param error - The error that occurred
	 */
	onError?: (error: Error) => void

	/**
	 * Timeout in milliseconds. If no matching message is received within this time,
	 * the listener is cleaned up and onError is called with a timeout error.
	 *
	 * Default: 30000 (30 seconds)
	 */
	timeout?: number
}

/**
 * Creates a one-time message listener with automatic cleanup and timeout protection.
 * 
 * This utility:
 * - Sets up a message event listener on the window
 * - Matches messages based on type and optional custom condition
 * - Automatically cleans up the listener after success, error, or timeout
 * - Prevents memory leaks with proper cleanup in all scenarios
 * - Returns a cleanup function for manual cleanup if needed
 * 
 * @param config - Configuration for the message listener
 * @returns A cleanup function that can be called to manually remove the listener
 * 
 * @example
 * ```typescript
 * // Listen for marketplace install result
 * const cleanup = createMessageListener({
 *   messageType: 'marketplaceInstallResult',
 *   matchCondition: (message) => message.slug === 'my-mode',
 *   onSuccess: (message) => {
 *     console.log('Installed successfully!');
 *   },
 *   onError: (error) => {
 *     console.error('Installation failed:', error);
 *   },
 *   timeout: 30000
 * });
 * 
 * // Later, if you need to cancel the listener early:
 * cleanup();
 * ```
 */
export function createMessageListener<T = any>(config: MessageListenerConfig<T>): () => void {
	const { messageType, matchCondition, onSuccess, onError, timeout = 30000 } = config

	let timeoutId: NodeJS.Timeout | null = null
	let isCleanedUp = false

	/**
	 * Cleanup function that removes the event listener and clears the timeout
	 */
	const cleanup = () => {
		if (isCleanedUp) {
			return
		}
		isCleanedUp = true

		window.removeEventListener("message", handleMessage)
		if (timeoutId) {
			clearTimeout(timeoutId)
			timeoutId = null
		}
	}

	/**
	 * Message event handler
	 */
	const handleMessage = (event: MessageEvent) => {
		const message = event.data

		// Check if message type matches
		if (message.type !== messageType) {
			return
		}

		// Check if custom match condition is satisfied (if provided)
		if (matchCondition && !matchCondition(message)) {
			return
		}

		// Handle success or error based on message.success flag
		if (message.success === false) {
			// Message indicates an error - always cleanup
			cleanup()
			const error = new Error(message.error || `${messageType} failed`)
			onError?.(error)
		} else {
			// Message indicates success (or no success flag, assume success)
			// Call onSuccess and check if it wants to keep listening
			const keepListening = onSuccess(message)
			
			// If onSuccess returns true, keep the listener active
			// Otherwise, clean up the listener
			if (!keepListening) {
				cleanup()
			}
		}
	}

	// Set up the event listener
	window.addEventListener("message", handleMessage)

	// Set up timeout protection
	timeoutId = setTimeout(() => {
		if (!isCleanedUp) {
			cleanup()
			const error = new Error(`Timeout waiting for ${messageType} (${timeout}ms)`)
			onError?.(error)
		}
	}, timeout)

	// Return cleanup function for manual cleanup if needed
	return cleanup
}