import { vscode } from "@/utils/vscode"
import { createMessageListener } from "./messageListener"
import type { UserProfile, ProfileId } from "../../../../src/shared/IBM/userProfileTypes"

/**
 * Get the active user profile from the extension.
 *
 * @param forceRefresh - If true, bypasses cache and fetches fresh data from the API
 * @returns Promise resolving to the active profile or null if no profiles exist
 */
export async function getActiveProfile(forceRefresh: boolean = false): Promise<UserProfile | null> {
	return vscode.postMessageAwaitResponse<UserProfile | null>({
		type: "getActiveProfile",
		bool: forceRefresh,
	})
}

/**
 * Get all user profiles from the extension.
 *
 * @param forceRefresh - If true, bypasses cache and fetches fresh data from the API
 * @returns Promise resolving to an array of all profiles (empty array if none exist)
 */
export async function getAllProfiles(forceRefresh: boolean = false): Promise<UserProfile[]> {
	return vscode.postMessageAwaitResponse<UserProfile[]>({
		type: "getAllProfiles",
		bool: forceRefresh,
	})
}

/**
 * Set the active user profile.
 *
 * @param profileId - The profile ID to set as active (format: "instance_id:team_id")
 * @returns Promise that resolves when the profile has been set
 * @throws Error if the profile ID is invalid or doesn't exist
 */
export async function setActiveProfile(profileId: ProfileId): Promise<void> {
	return new Promise((resolve, reject) => {
		// Send the message first
		vscode.postMessage({
			type: "setActiveProfile",
			text: profileId,
		})

		// Set up listener for confirmation with automatic cleanup
		// The extension broadcasts profilesUpdated when the active profile changes
		createMessageListener({
			messageType: "profilesUpdated",
			onSuccess: () => {
				resolve()
			},
			onError: (error) => {
				reject(error)
			},
			timeout: 10000, // 10 seconds
		})
	})
}

