import { useState, useEffect, useRef, useMemo } from "react"
import { getActiveProfile } from "@/ibm/utils/userProfile"
import { UserProfile } from "../../../../src/shared/IBM/userProfileTypes"
import { useTranslation } from "react-i18next"
import { logger } from "../utils/logger"
import { useExtensionState } from "@/context/ExtensionStateContext"

export interface Budget {
	percentage: number
	spend: string
	limit: string | null
	email: string
}

const BUDGET_REFRESH_INTERVAL_MS = 5 * 60 * 1000 // 5 minutes

/**
 * Calculates budget information from user profile data
 *
 * @param profile The user profile from UserProfileService
 * @param unlimitedLabel Label to display for unlimited budgets
 * @returns Budget object or null if required data is missing
 */
const calculateBudgetFromProfile = (
	profile: UserProfile | null | undefined,
	unlimitedLabel: string,
): Budget | null => {
	if (!profile) {
		return null
	}

	const { usage, budget_limit, user_id } = profile

	// Handle null usage (rare but possible)
	if (usage === null || usage === undefined) {
		return null
	}

	// Calculate percentage remaining
	// If budget_limit is null, it means unlimited budget (100%)
	const percentage = budget_limit ? Math.floor(100 - (usage / budget_limit) * 100) : 100

	return {
		percentage,
		spend: usage.toFixed(2),
		limit: budget_limit ? budget_limit.toFixed(2) : unlimitedLabel,
		email: user_id || "",
	}
}

/**
 * Hook to manage budget information
 *
 * This hook handles:
 * - Calculating budget directly from activeProfile in extension state
 * - Refreshing profile data on a regular interval to keep budget current
 * - Automatically recalculating when the active profile changes
 * - Works with both Gateway API and LiteLLM endpoints
 *
 * @returns Budget information and related functions
 */
export const useBudget = () => {
	const { t } = useTranslation("ibm")
	const { activeProfile } = useExtensionState()
	const [isLoading, setIsLoading] = useState<boolean>(false)

	// Refresh profile data on a regular interval ref
	const intervalIdRef = useRef<NodeJS.Timeout | undefined>()

	// Calculate budget directly from activeProfile in extension state
	// This automatically updates when activeProfile changes
	const budget = useMemo(() => {
		return calculateBudgetFromProfile(activeProfile, t("budget.unlimited"))
	}, [activeProfile, t])

	/**
	 * Refreshes the active profile to get the latest budget data
	 * This triggers a profile update in the extension, which will update activeProfile in state
	 */
	const refreshProfile = async () => {
		setIsLoading(true)
		try {
			// Force refresh the active profile from the backend
			// This will trigger a profilesUpdated message that updates extension state
			await getActiveProfile(true)
		} catch (error) {
			logger.error("Failed to refresh profile for budget update:", error)
		} finally {
			setIsLoading(false)
		}
	}

	useEffect(() => {
		// Initial profile refresh when component mounts or profile changes
		refreshProfile()

		// Set up interval to refresh profile every 5 minutes
		intervalIdRef.current = setInterval(refreshProfile, BUDGET_REFRESH_INTERVAL_MS)

		// Clean up interval on unmount or when active profile changes
		return () => clearInterval(intervalIdRef.current)
	}, [activeProfile]) // Re-fetch when profile changes

	return { budget, isLoading, fetchBudget: refreshProfile }
}

